# Synthetic data generated by Synthea — not real patient records.
"""Clinical pillar pipeline: Synthea -> FHIR -> parquet -> summary.

    python -m packages.pipelines.synth.run_all --population 10000 --seed 42

Used by .github/workflows/clinical-refresh.yml (nightly). Writes
data/processed/clinical/{events,patients}.parquet (last --window-days of
encounters/observations; all conditions) and fails if they exceed --max-mb.
"""
from __future__ import annotations

import argparse
import os
import sys
import time
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

if __package__ in (None, ""):  # allow `python packages/pipelines/synth/run_all.py`
    sys.path.insert(0, str(Path(__file__).resolve().parents[3]))

from packages.pipelines.synth.synthea_wrapper import (  # noqa: E402
    SYNTHETIC_NOTICE, daily_aggregate, parse_fhir_bundles, run_synthea_uae)


def _table(rows: list[tuple[str, object]]) -> str:
    w = max(len(k) for k, _ in rows)
    return "\n".join(f"  {k.ljust(w)}  {v}" for k, v in rows)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--population", type=int, default=10000)
    ap.add_argument("--seed", type=int, default=42)
    ap.add_argument("--raw-dir", type=Path, default=Path("data/raw/clinical"))
    ap.add_argument("--out-dir", type=Path, default=Path("data/processed/clinical"))
    ap.add_argument("--window-days", type=int, default=90)
    ap.add_argument("--reference-date", type=date.fromisoformat, default=None,
                    help="simulate through the end of this UTC date (default: today)")
    ap.add_argument("--skip-synthea", action="store_true",
                    help="re-parse an existing FHIR export in --raw-dir/fhir")
    ap.add_argument("--max-mb", type=float, default=50.0)
    ap.add_argument("--workers", type=int, default=os.cpu_count() or 1)
    args = ap.parse_args(argv)

    print(SYNTHETIC_NOTICE)
    ref = args.reference_date or datetime.now(timezone.utc).date()
    t0 = time.time()
    if args.skip_synthea:
        fhir = args.raw_dir / "fhir"
    else:
        print(f"[1/3] Synthea: population={args.population} seed={args.seed} through {ref} UTC")
        fhir = run_synthea_uae(args.population, args.seed, args.raw_dir, reference_date=ref)
    t1 = time.time()

    print(f"[2/3] Parsing FHIR bundles in {fhir}")
    events = parse_fhir_bundles(fhir, out_dir=args.out_dir, window_days=args.window_days,
                                as_of=ref, workers=args.workers)
    t2 = time.time()

    import pandas as pd
    patients = pd.read_parquet(args.out_dir / "patients.parquet")
    sizes = {p.name: p.stat().st_size / 1e6 for p in args.out_dir.glob("*.parquet")}
    total_mb = sum(sizes.values())

    print("[3/3] Summary")
    alive = patients[~patients["deceased"]]
    last7 = daily_aggregate(events, ref - timedelta(days=6), ref)
    print(_table([
        ("patients (alive / total)", f"{len(alive):,} / {len(patients):,}"),
        ("events", f"{len(events):,}  " + str(events['event_type'].value_counts().to_dict())),
        ("male share", f"{(alive['gender'] == 'male').mean():.1%}"),
        ("age 35-44 / 65+", f"{alive['age'].between(35, 44).mean():.1%} / {(alive['age'] >= 65).mean():.1%}"),
        ("cities", len(alive['city'].unique())),
        ("parquet", ", ".join(f"{k} {v:.1f} MB" for k, v in sorted(sizes.items()))),
        ("timing", f"synthea {t1 - t0:.0f}s, parse {t2 - t1:.0f}s"),
    ]))
    print("\nLast 7 days (UTC):")
    print(last7.to_string(index=False))

    if total_mb > args.max_mb:
        print(f"ERROR: parquet total {total_mb:.1f} MB exceeds --max-mb {args.max_mb}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
